  "annotations": [
    {
      "keyword_id": "multi-label-learning",
      "exact_quote": "Hierarchical multi-label prediction of gene function",
      "evidence_field": "title",
      "reason_zh": "标题直接表明是多标记预测任务，即为单个基因预测多个功能标记。"
    },
    {
      "keyword_id": "classifier-ensemble",
      "exact_quote": "Using a hierarchy of support vector machine (SVM) classifiers trained on multiple data types, we combined predictions in our Bayesian framework",
      "evidence_field": "abstract",
      "reason_zh": "结合多个SVM分类器的预测以获得一致功能预测，属于分类器集成。"
    },
    {
      "keyword_id": "bayesian-inference",
      "exact_quote": "we combined predictions in our Bayesian framework to obtain the most probable consistent set of predictions",
      "evidence_field": "abstract",
      "reason_zh": "使用贝叶斯框架融合预测并求最可能一致预测集，进行后验推断。"
    },
    {
      "keyword_id": "label-correlation-modeling",
      "exact_quote": "Taking the hierarchical structure into account resolves such inconsistencies",
      "evidence_field": "abstract",
      "reason_zh": "显式利用功能类层次结构（父子依赖）解决不一致预测，建模标签间层级相关结构。"
    },
    {
      "keyword_id": "confidence-calibration",
      "exact_quote": "our method also provides implicit calibration of SVM margin outputs to probabilities",
      "evidence_field": "abstract",
      "reason_zh": "方法将SVM margin输出隐式校准为概率，使置信度与正确概率相符。"
    }
  ],
  "abstentions": [
    {
      "keyword_id": "multi-view-learning",
      "reason_zh": "摘要仅提及使用多种数据类型训练SVM，未说明是否显式联合利用多个视图间关系，可能只是特征拼接，定义不满足。"
    }
  ],
